docs(cookbook): add WebMCP shopping cart recipe (#25192)

## Background

The WebMCP example in #25186 only reads a cart. Developers need a
cookbook showing how browser-owned tools reach a server-side AI SDK
model and execute back in the page.

Stacked on #25186: `aayush/237` → `aayush/236`.

## Summary

- Add a Next.js cookbook recipe covering registration,
`WebMCPTransport`, **`createMCPTools`**, and `useChat` tool execution.
- Turn the example into a responsive storefront with free-form
conversation and read/add/update/remove tools sharing live cart state
with the UI.
- Validate product IDs and quantities, preserve console logging, and
link the recipe from the MCP guide and example README.

Checks passed: workspace package builds, `pnpm type-check:full`,
targeted lint/format checks, docs validation, MDX compilation, and
applicable verifiers. No published-package changes.

## End-to-End Verification

Verified with native WebMCP in Chrome 157 and real OpenAI calls. The
conversation produced totals **$25 → $49 → $61 → $36 → $54**, including
a manual UI change read back by the agent. All 10 chat requests returned
HTTP 200 with no page errors. Native CRUD and invalid input checks
passed; desktop and 375/390px mobile layouts were inspected.

<details>
<summary>Setup and runnable browser verification</summary>

Set `OPENAI_API_KEY` in `examples/ai-e2e-next/.env.local`, install
Chrome, and build this checkout's local packages:

```sh
pnpm exec turbo build --filter=@ai-sdk/mcp... --filter=@ai-sdk/react... --filter=@ai-sdk/openai... --filter=ai...
pnpm --filter @example/next-openai dev
```

Save the script below to `/tmp/webmcp-check.mjs`. With the app on port
3000, run from the repository root so Playwright resolves from the
workspace:

```sh
node --input-type=module < /tmp/webmcp-check.mjs
```

The browser enables experimental WebMCP flags. Browser tools, the MCP
client/helper, and the API route all use this checkout; no tool or
provider responses are mocked.

```js
import { chromium } from 'playwright';
import assert from 'node:assert/strict';

const browser = await chromium.launch({
  channel: 'chrome',
  headless: true,
  args: ['--enable-experimental-web-platform-features', '--enable-features=WebMCPTesting'],
});
try {
  const page = await browser.newPage({ viewport: { width: 1440, height: 1100 } });
  const calls = [];
  const errors = [];
  const statuses = [];
  page.on('pageerror', error => errors.push(error.message));
  page.on('console', message => {
    if (message.text().startsWith('[WebMCP] Tool')) calls.push(message.text());
  });
  page.on('response', response => {
    if (response.url().endsWith('/api/chat/webmcp')) statuses.push(response.status());
  });
  await page.goto('http://127.0.0.1:3000/chat/webmcp');
  const input = page.getByRole('textbox', { name: 'Message', exact: true });
  await input.waitFor();
  await page.waitForFunction(() => !document.querySelector('textarea')?.disabled);
  console.log('Tools:', await page.evaluate(async () => (await document.modelContext.getTools()).map(t => t.name)));

  async function nativeCall(name, args) {
    return page.evaluate(async ({ name, args }) => {
      const tools = await document.modelContext.getTools();
      return JSON.parse(await document.modelContext.executeTool(tools.find(t => t.name === name), args));
    }, { name, args });
  }
  assert.equal((await nativeCall('getCart', {})).total, 25);
  // Consecutive mutations must see the same current state even before React renders.
  await nativeCall('addToCart', { productId: 'mug', quantity: 2 });
  assert.equal((await nativeCall('updateCartItem', { productId: 'mug', quantity: 3 })).total, 61);
  assert.equal((await nativeCall('removeFromCart', { productId: 'mug' })).total, 25);
  for (const args of [{ productId: 'mug', quantity: -1 }, { productId: 'mug', quantity: 21 }, { productId: 'unknown', quantity: 1 }]) {
    await assert.rejects(nativeCall('addToCart', args));
  }
  assert.equal((await nativeCall('getCart', {})).total, 25);
  await page.screenshot({ path: '/tmp/ai-sdk-webmcp-cookbook-desktop.png', fullPage: true });

  async function chat(text, expectedTotal) {
    await input.fill(text);
    await page.getByRole('button', { name: 'Send message', exact: true }).click();
    await page.waitForFunction(() => document.querySelector('textarea')?.disabled, undefined, { timeout: 10000 });
    await page.waitForFunction(() => !document.querySelector('textarea')?.disabled, undefined, { timeout: 120000 });
    const alerts = page.locator('main [role=alert]');
    console.log('Chat alerts:', await alerts.allTextContents());
    if (await alerts.count()) console.log('Call diagnostics:', { calls, errors, statuses });
    assert.equal(await alerts.count(), 0, 'No chat errors');
    const snapshot = await nativeCall('getCart', {});
    assert.equal(snapshot.total, expectedTotal, text);
    console.log(JSON.stringify({ prompt: text, total: snapshot.total, items: snapshot.items }));
  }
  await chat('What is in my cart?', 25);
  await chat('Add two mugs.', 49);
  await chat('Set the mug quantity to three.', 61);
  await chat("Remove the T-shirt. What is the total now?", 36);
  await page.getByRole('button', { name: 'Add Canvas tote', exact: true }).click();
  await chat('What is the total now? Read the current cart.', 54);
  console.log('Conversation:', await page.getByLabel('Conversation', { exact: true }).innerText());
  console.log(JSON.stringify({ browser: browser.version(), statuses, calls, errors }));
  assert.equal(errors.length, 0);
  assert(statuses.length > 0 && statuses.every(status => status === 200));
  await page.screenshot({ path: '/tmp/ai-sdk-webmcp-cookbook-desktop-chat.png', fullPage: true });
  await page.setViewportSize({ width: 390, height: 844 });
  await page.screenshot({ path: '/tmp/ai-sdk-webmcp-cookbook-mobile.png', fullPage: true });
  assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), 'No horizontal overflow');
  console.log('PASS: native CRUD, validation, real-model conversation, live UI state, mobile layout');
} finally {
  await browser.close();
}
```

</details>

