    description: 'Read the current cart',
    annotations: { readOnlyHint: true },
    execute: async () => ({
      quantity: document.querySelector('#quantity').valueAsNumber,
      total: document.querySelector('#quantity').valueAsNumber * 25,
    }),
  });
  const client = await createMCPClient({
    transport: new WebMCPTransport({ modelContext: document.modelContext }),
